def _pick_block(total, cap=_MAX_BLOCK):
    """Block size that keeps the program count within a couple of waves."""
    if total <= 0:
        return _MIN_BLOCK
    target = _num_vectorcore() * 2
    b = -(-total // target)
    if b <= 1:
        return _MIN_BLOCK
    block = 1 << (b - 1).bit_length()
    if block < _MIN_BLOCK:
        return _MIN_BLOCK
    if block > cap:
        return cap
    return block


