def _launch_strided(t, acc):
    n = t.numel()
    if n == 0:
        return
    dims = _collapse(t)
    if len(dims) > _DIMS:
        # Not reachable for realistic views: peel the leading dimension (a
        # metadata-only view) and recurse so the index formula always fits.
        for i in range(t.shape[0]):
            _launch_strided(t.select(0, i), acc)
        return
    args = []
    for k in range(_DIMS):
        if k < len(dims):
            args.append(dims[k][0])
            args.append(dims[k][1])
        else:
            args.append(1)
            args.append(0)
    block = _pick_block(n, _MAX_BLOCK_STRIDED)
    _expm1_strided[(-(-n // block),)](t, n, *args, BLOCK=block, ACC=acc)


def _acc_of(dtype):
    return tl.float64 if dtype is torch.float64 else tl.float32


def _check_float(t):
    dt = t.dtype
    if not dt.is_floating_point:
        raise RuntimeError(
            "result type Float can't be cast to the desired output type "
            + _DTNAME.get(dt, str(dt).replace("torch.", ""))
        )
    if _internal_overlap(t):
        raise RuntimeError(_OVERLAP_MSG)


def foreach_expm1_(self):
    ts = self
    if not isinstance(ts, (list, tuple)):
        raise TypeError("argument 'self' must be tuple of Tensors")
    n = len(ts)
    if n == 0:
        raise RuntimeError("Tensor list must have at least one tensor.")
    for t in ts:
        if not isinstance(t, torch.Tensor):
            raise TypeError("argument 'self' must be tuple of Tensors")

    flats = {}
    gappies = {}
    aliased = False
    if n == 1:
        t = ts[0]
        _check_float(t)
        if _flat_addressable(t):
            flats.setdefault(t.dtype, []).append(t)
        else:
            gappies.setdefault(t.dtype, []).append(t)
    else:
        lo = []
        hi = []
        for t in ts:
            dt = t.dtype
            if not dt.is_floating_point:
                raise RuntimeError(
                    "result type Float can't be cast to the desired output type "
                    + _DTNAME.get(dt, str(dt).replace("torch.", ""))
                )
            # Hot path first: one is_contiguous probe serves both the layout
            # class and the (impossible for contiguous) overlap check.
            if t.is_contiguous():
                p = t.data_ptr()
                lo.append(p)
                hi.append(p + t.numel() * t.element_size())
                group = flats.get(dt)
                if group is None:
                    flats[dt] = [t]
                else:
                    group.append(t)
                continue
            if _internal_overlap(t):
                raise RuntimeError(_OVERLAP_MSG)
            flat = _flat_addressable(t)
            p = t.data_ptr()
            lo.append(p)
            hi.append(p + (t.numel() if flat else _reach(t)) * t.element_size())
            groups = flats if flat else gappies
            group = groups.get(dt)
            if group is None:
                groups[dt] = [t]
            else:
                group.append(t)
        # If the list could contain aliasing elements, ATen's strictly
        # sequential order matters and a fused launch would race.
        spans = 0
        for a, b in zip(lo, hi):
            spans += b - a
        aliased = (max(hi) - min(lo)) < spans

    if aliased:
        for t in ts:
            acc = _acc_of(t.dtype)
            if _flat_addressable(t):
                _launch_flat_single(t, acc)
            else:
                _launch_strided(t, acc)
        return None

    for key, group in flats.items():
        _launch_flat(group, _acc_of(key))
    for key, group in gappies.items():
        acc = _acc_of(key)
        for t in group:
            _launch_strided(t, acc)
    return None
